+import {
+  listRecentSessions,
+  listRecentPayments,
+  listAllPayouts,
+} from "@/lib/db/queries";
+import { shortDate } from "@/lib/time";
+import { t } from "@/lib/i18n";
+
+export const metadata = {
+  title: `${t("admin.activityTitle")} · ${t("app.name")}`,
+};
+
+export default async function AdminActivityPage() {
+  await requireRole("admin");
+  const [sessions, payments, payouts] = await Promise.all([
+    listRecentSessions(25),
+    listRecentPayments(25),
+    listAllPayouts(25),
+  ]);
