+import { Card } from "@/components/ui/Card";
+import { DashboardHeader } from "@/components/dashboard/DashboardHeader";
+import { ReportCard } from "@/components/admin/ReportCard";
+import { requireRole } from "@/lib/auth";
+import { listReports, getProfilesByIds } from "@/lib/db/queries";
+import { shortDate } from "@/lib/time";
+import { t } from "@/lib/i18n";
+
+export const metadata = { title: `${t("admin.reportsTitle")} · ${t("app.name")}` };
+
+export default async function AdminReportsPage() {
+  await requireRole("admin");
+  const reports = await listReports();
+
+  const ids = Array.from(
+    new Set(
+      reports.flatMap((r) => [r.reporter_id, r.target_id].filter(Boolean)),
+    ),
+  ) as string[];
+  const profiles = await getProfilesByIds(ids);
+  const nameFor = (id: string | null) =>
+    (id && (profiles.get(id)?.full_name || profiles.get(id)?.email)) || "—";
+
+  return (
+    <div className="flex flex-col gap-6">
+      <DashboardHeader
+        title={t("admin.reportsTitle")}
+        description={t("admin.reportsSubtitle")}
+      />
+
+      {reports.length === 0 ? (
+        <Card>
+          <p className="text-base text-ink-soft">{t("admin.reportsNone")}</p>
+        </Card>
+      ) : (
+        <ul className="flex flex-col gap-4">
+          {reports.map((r) => (
+            <ReportCard
+              key={r.id}
+              report={{
+                id: r.id,
+                reason: r.reason,
+                status: r.status,
+                whenLabel: shortDate(r.created_at),
+                reporterName: nameFor(r.reporter_id),
+                targetId: r.target_id,
+                targetName: r.target_id ? nameFor(r.target_id) : null,
+              }}
+            />
+          ))}
+        </ul>
+      )}
+    </div>
+  );
+}
