+"use client";
+
+import * as React from "react";
+import { DataTable, type Column } from "@/components/ui/DataTable";
+import { StatusBadge, type StatusTone } from "@/components/ui/StatusBadge";
+import { formatCents } from "@/lib/format";
+import { t } from "@/lib/i18n";
+
+export interface AdminSessionRow {
+  id: string;
+  dateLabel: string;
+  dateMs: number;
+  durationLabel: string;
+  totalCents: number;
+  commissionCents: number;
+  earningsCents: number;
+  status: string;
+}
+export interface AdminPaymentRow {
+  id: string;
+  dateLabel: string;
+  dateMs: number;
+  amountCents: number;
+  status: string;
+}
+export interface AdminPayoutRow {
+  id: string;
+  periodLabel: string;
+  periodMs: number;
+  amountCents: number;
+  status: string;
+}
+
+const PAYMENT_TONE: Record<string, StatusTone> = {
+  authorized: "neutral",
+  captured: "success",
+  refunded: "neutral",
+  failed: "alert",
+};
+const SESSION_TONE: Record<string, StatusTone> = {
+  completed: "success",
+  in_progress: "info",
+  cancelled: "neutral",
+};
+const PAYOUT_TONE: Record<string, StatusTone> = {
+  paid: "success",
+  scheduled: "warning",
+};
+
+function Badge({ tone, label }: { tone: StatusTone; label: string }) {
+  return <StatusBadge tone={tone}>{label}</StatusBadge>;
+}
+
+export function AdminActivityTables({
+  sessions,
+  payments,
+  payouts,
+}: {
+  sessions: AdminSessionRow[];
+  payments: AdminPaymentRow[];
+  payouts: AdminPayoutRow[];
+}) {
+  const sessionCols: Column<AdminSessionRow>[] = [
+    { key: "dateLabel", header: t("admin.colDate"), sortable: true, sortValue: (r) => r.dateMs },
+    { key: "durationLabel", header: t("provider.colDuration") },
+    { key: "totalCents", header: t("admin.colAmount"), align: "right", sortable: true, sortValue: (r) => r.totalCents, render: (r) => formatCents(r.totalCents) },
+    { key: "commissionCents", header: t("admin.colCommission"), align: "right", render: (r) => formatCents(r.commissionCents) },
+    { key: "earningsCents", header: t("admin.colEarnings"), align: "right", render: (r) => formatCents(r.earningsCents) },
+    { key: "status", header: t("admin.colStatus"), render: (r) => <Badge tone={SESSION_TONE[r.status] ?? "neutral"} label={r.status} /> },
+  ];
+  const paymentCols: Column<AdminPaymentRow>[] = [
+    { key: "dateLabel", header: t("admin.colDate"), sortable: true, sortValue: (r) => r.dateMs },
+    { key: "amountCents", header: t("admin.colAmount"), align: "right", sortable: true, sortValue: (r) => r.amountCents, render: (r) => formatCents(r.amountCents) },
+    { key: "status", header: t("admin.colStatus"), render: (r) => <Badge tone={PAYMENT_TONE[r.status] ?? "neutral"} label={r.status} /> },
+  ];
+  const payoutCols: Column<AdminPayoutRow>[] = [
+    { key: "periodLabel", header: t("provider.colPeriod"), sortable: true, sortValue: (r) => r.periodMs },
+    { key: "amountCents", header: t("admin.colAmount"), align: "right", sortable: true, sortValue: (r) => r.amountCents, render: (r) => formatCents(r.amountCents) },
+    { key: "status", header: t("admin.colStatus"), render: (r) => <Badge tone={PAYOUT_TONE[r.status] ?? "neutral"} label={r.status} /> },
+  ];
+
+  return (
+    <>
+      <section className="flex flex-col gap-4">
+        <h2 className="text-h2">{t("admin.sessionsHeading")}</h2>
+        <DataTable caption={t("admin.sessionsCaption")} columns={sessionCols} rows={sessions} getRowKey={(r) => r.id} emptyText={t("admin.sessionsNone")} />
+      </section>
+      <section className="flex flex-col gap-4">
+        <h2 className="text-h2">{t("admin.paymentsHeading")}</h2>
+        <DataTable caption={t("admin.paymentsCaption")} columns={paymentCols} rows={payments} getRowKey={(r) => r.id} emptyText={t("admin.paymentsNone")} />
+      </section>
+      <section className="flex flex-col gap-4">
+        <h2 className="text-h2">{t("admin.payoutsTableHeading")}</h2>
+        <DataTable caption={t("admin.payoutsTableCaption")} columns={payoutCols} rows={payouts} getRowKey={(r) => r.id} emptyText={t("provider.payoutsNone")} />
+      </section>
+    </>
+  );
+}
