+"use client";
+
+import * as React from "react";
+import { useRouter, useSearchParams } from "next/navigation";
+import { Search } from "lucide-react";
+import { Button } from "@/components/ui/Button";
+import { Field, Input } from "@/components/ui/Field";
+import { t } from "@/lib/i18n";
+
+export function AdminUserSearch() {
+  const router = useRouter();
+  const params = useSearchParams();
+  const [value, setValue] = React.useState(params.get("q") ?? "");
+
+  function submit(e: React.FormEvent) {
+    e.preventDefault();
+    const next = new URLSearchParams();
+    if (value.trim()) next.set("q", value.trim());
+    router.push(`/admin/users${next.toString() ? `?${next}` : ""}`);
+  }
+
+  return (
+    <form onSubmit={submit} className="flex flex-wrap items-end gap-3">
+      <Field label={t("admin.usersSearchLabel")}>
+        {(p) => (
+          <Input
+            {...p}
+            type="search"
+            value={value}
+            onChange={(e) => setValue(e.target.value)}
+            placeholder={t("admin.usersSearchPlaceholder")}
+          />
+        )}
+      </Field>
+      <Button type="submit" icon={Search}>
+        {t("admin.usersSearch")}
+      </Button>
+    </form>
+  );
+}
diff --git a/components/admin/ReportCard.tsx b/components/admin/ReportCard.tsx
