  reason: "The caller was hostile.",
  status: "open" as const,
  whenLabel: "Jun 8, 2026",
  reporterName: "Walter",
  targetId: "c1",
  targetName: "Casey",
};

describe("ReportCard", () => {
  it("shows the report and actions with no a11y violations", async () => {
    const { container } = renderWithProviders(
      <ul>
        <ReportCard report={REPORT} />
      </ul>,
    );
    expect(screen.getByText(/the caller was hostile/i)).toBeInTheDocument();
    expect(screen.getByText(/from: walter/i)).toBeInTheDocument();
    expect(await axe(container)).toHaveNoViolations();
  });

  it("marks reviewed and suspends the target", async () => {
    const user = userEvent.setup();
    renderWithProviders(
      <ul>
        <ReportCard report={REPORT} />
      </ul>,
    );
    await user.click(screen.getByRole("button", { name: /mark reviewed/i }));
    expect(resolveReport).toHaveBeenCalledWith("r1");
    await user.click(screen.getByRole("button", { name: /suspend the reported user/i }));
    expect(setUserSuspended).toHaveBeenCalledWith({ userId: "c1", suspended: true });
  });
});

describe("UsersTable", () => {
  const rows = [
    { id: "u1", name: "Casey", email: "casey@x.com", role: "customer" as const, suspended: false },
    { id: "u2", name: "Maya", email: "maya@x.com", role: "provider" as const, suspended: true },
    { id: "u3", name: "Avery", email: "admin@x.com", role: "admin" as const, suspended: false },
  ];

  it("renders a semantic table; admins have no suspend action; no a11y violations", async () => {
    const { container } = renderWithProviders(<UsersTable rows={rows} />);
    expect(screen.getByRole("table", { name: /customers and listeners/i })).toBeInTheDocument();
    // 2 actionable users (customer + provider); admin row shows no button
    expect(screen.getByRole("button", { name: /^suspend$/i })).toBeInTheDocument();
    expect(screen.getByRole("button", { name: /reinstate/i })).toBeInTheDocument();
    expect(await axe(container)).toHaveNoViolations();
  });

  it("suspends an active user", async () => {
    const user = userEvent.setup();
    renderWithProviders(<UsersTable rows={rows} />);
    await user.click(screen.getByRole("button", { name: /^suspend$/i }));
    expect(setUserSuspended).toHaveBeenCalledWith({ userId: "u1", suspended: true });
  });
});

